using System;
using System.Collections.Generic;

namespace Plugin2.VolumeEstimator.Revit
{
    internal static class EmbeddedIconData
    {
        private static readonly Dictionary<string, string> Data = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase)
        {
            { "buildai32", "" },
            { "connect16", "" },
            { "connect32", "" },
            { "open16", "" },
            { "open32", "" },
            { "recalculate16", "" },
            { "recalculate32", "" },
            { "ribbonicon16", "" },
            { "ribbonicon32", "" },
            { "support16", "" },
            { "support32", "" },
            { "syncback16", "" },
            { "syncback32", "" },
        };

        public static bool TryGet(string key, out byte[] bytes)
        {
            bytes = null;
            string value;
            if (!Data.TryGetValue(key ?? string.Empty, out value)) return false;
            try { bytes = Convert.FromBase64String(value); return bytes != null && bytes.Length > 0; }
            catch { return false; }
        }
    }
}